-- ============================================================
-- Reemplaza el pénsum genérico/aproximado de Ingeniería de Sistemas
-- (carrera 10000000-0000-0000-0000-000000000001) por el real,
-- provisto por el usuario.
--
-- La materia 'Bases de Datos' (20000000-0000-0000-0000-000000000007)
-- se conserva intacta: tiene una oferta y un documento real subidos
-- por un usuario en producción, y su nombre ya coincide con el
-- pénsum real. El resto de materias viejas (aproximadas) no tienen
-- ningún documento asociado y se eliminan sin riesgo.
-- ============================================================

delete from public.materias
  where carrera_id = '10000000-0000-0000-0000-000000000001'
    and id <> '20000000-0000-0000-0000-000000000007';

